makeMtLab(document.getElementById("lab-l114"),{id:"l114",scenarios:[{"label": "Ví dụ: Máy chủ hỏng ổ đĩa 08:00", "note": "Khôi phục.", "steps": [{"t": "Bản sao lưu mới nhất 22:15 hôm qua", "html": "<p class=\"mt-calc\">Khôi phục lên máy dự phòng: 25 phút<\/p>"}, {"t": "Dữ liệu máy từ 22:15", "html": "<p class=\"mt-calc\">Outbox của collector gửi lại khi CSDL có lại<\/p>"}, {"t": "Kết quả", "html": "<p class=\"mt-calc\">RTO đo được 25 phút; dữ liệu nhập tay sau 22:15 cần nhập lại<\/p>", "ask": {"q": "Dữ liệu máy có mất không?", "o": ["Mất 10 giờ", "Không, outbox gửi lại"], "a": 1}}]}, {"label": "Ví dụ: Kiểm file sao lưu", "note": "pg_restore -l.", "steps": [{"t": "File đọc được mục lục", "html": "<p class=\"mt-calc\">Không hỏng<\/p>"}, {"t": "File 0 byte", "html": "<p class=\"mt-calc\">Báo lỗi ngay, không chờ tới lúc cần<\/p>"}]}, {"label": "Ví dụ: Đối chiếu sau khôi phục", "note": "Truy vấn chuẩn.", "steps": [{"t": "count(*) state_event", "html": "<p class=\"mt-calc\">Khớp số lúc sao lưu<\/p>"}, {"t": "OEE ca chuẩn", "html": "<p class=\"mt-calc\">0,7556: đúng<\/p>"}]}, {"label": "Lỗi: Sao lưu cùng ổ đĩa", "note": "Một nơi.", "steps": [{"t": "Ổ hỏng", "html": "<p class=\"mt-calc\">Mất cả CSDL và bản sao lưu<\/p>"}, {"t": "Sửa", "html": "<p class=\"mt-calc\">Bản sao ở máy khác, nơi khác<\/p>"}]}, {"label": "Bẫy: Mật khẩu trong compose", "note": "Đẩy lên kho mã.", "steps": [{"t": "Ai đọc kho mã cũng thấy", "html": "<p class=\"mt-calc\">Lộ mật khẩu CSDL<\/p>"}, {"t": "Sửa", "html": "<p class=\"mt-calc\">secrets, file ngoài kho mã<\/p>"}]}]});
makeMtEx(document.getElementById("ex-l114"),"l114",[{"kind": "num", "t": "Sao lưu", "d": "<p>Trả lời bằng một số.<\/p>", "items": [{"q": "Giữ 7 bản ngày, 4 bản tuần, 12 bản tháng. Tổng bao nhiêu bản?", "a": 23}, {"q": "Sao lưu mỗi 6 giờ. RPO tối đa (giờ)?", "a": 6}, {"q": "Khôi phục mất 25 phút, mục tiêu RTO 60 phút. Còn dư bao nhiêu phút?", "a": 35}], "hints": ["Cộng các bản.", "RPO = khoảng sao lưu."], "why": "23; 6; 35."}, {"kind": "pick", "t": "RPO hay RTO?", "d": "<p>Chỉ số nào?<\/p>", "cats": ["RPO", "RTO"], "items": [{"q": "Mất tối đa bao nhiêu dữ liệu", "a": 0}, {"q": "Bao lâu hệ thống chạy lại", "a": 1}, {"q": "Sao lưu mỗi ngày", "a": 0}, {"q": "Khôi phục mất 25 phút", "a": 1}], "hints": ["Point: dữ liệu.", "Time: thời gian chạy lại."], "why": "Mất dữ liệu, mỗi ngày: RPO; chạy lại, 25 phút: RTO."}, {"kind": "order", "t": "Diễn tập khôi phục", "d": "<p>Sắp xếp.<\/p>", "items": ["Chọn bản sao lưu", "Tạo CSDL thử mới", "pg_restore", "Đối chiếu số dòng và OEE ca chuẩn", "Ghi thời gian, cập nhật RTO"], "hints": ["CSDL mới trước khi khôi phục.", "Ghi kết quả ở cuối."], "why": "Chọn → tạo → restore → đối chiếu → ghi."}]);
mesSim(document.getElementById("sim-l114"),Object.assign({id:"l114"},{kind:"term",title:"Sao lưu và diễn tập khôi phục",sub:"Lệnh theo bài (PENDING: chạy thử với Docker trên máy chủ). Số dòng trong mô phỏng là minh họa.",cwd:"/srv/mini-mes",vars:{dump:false,db:false,rest:false},
 prompt:S=>"admin@mes-srv:"+S.cwd+"$ ",hints:["pg_dump -h db -U postgres -Fc -f mes_2026-11-11_2215.dump mes","pg_restore -l mes_2026-11-11_2215.dump | head","createdb -h db_test -U postgres mes_restore","pg_restore -h db_test -U postgres -d mes_restore mes_2026-11-11_2215.dump","psql -h db_test -d mes_restore -c \"SELECT count(*) FROM mes.state_event\"","psql -h db_test -d mes_restore -f sql/02_oee.sql"],
 cmds:[{re:/^pg_dump -h db -U postgres -Fc -f (mes_[\w-]+\.dump) mes$/,out:(m,S)=>"(không in gì khi thành công) → "+m[1],fx:(m,S)=>{S.dump=m[1]}},
  {re:/^pg_restore -l (\S+\.dump)( \| head)?$/,out:(m,S)=>S.dump===m[1]?";\n; Archive created at 2026-11-11 22:15:03 +07\n;     dbname: mes\n;     Format: CUSTOM\n… (đọc được mục lục: file không hỏng)":{err:"pg_restore: error: could not open input file \""+m[1]+"\": No such file or directory"}},
  {re:/^createdb -h db_test -U postgres mes_restore$/,out:"",fx:(m,S)=>{S.db=true}},
  {re:/^pg_restore -h db_test -U postgres -d mes_restore (\S+\.dump)$/,out:(m,S)=>!S.db?{err:"pg_restore: error: connection to server failed: FATAL:  database \"mes_restore\" does not exist"}:S.dump!==m[1]?{err:"pg_restore: error: could not open input file"}:"(không in gì khi thành công)",fx:(m,S)=>{if(S.db&&S.dump===m[1])S.rest=true}},
  {re:/^psql -h db_test -d mes_restore -c "SELECT count\(\*\) FROM mes\.state_event"$/,out:(m,S)=>S.rest?" count \n-------\n  2184\n(1 row)\n(so với số dòng ghi lại lúc sao lưu)":{err:"psql: error: relation \"mes.state_event\" does not exist"}},
  {re:/^psql -h db_test -d mes_restore -f sql\/02_oee\.sql$/,out:(m,S)=>S.rest?" machine_id | planned_s | run_s | oee\n------------+-----------+-------+--------\n L1-M1      |     27000 | 23400 | 0.7556\n(1 row)":{err:"psql: error: relation does not exist"}}],
 tasks:[{t:"Sao lưu CSDL bằng pg_dump định dạng custom.",check:s=>!!s.S.dump},
  {t:"Kiểm file sao lưu đọc được mục lục.",check:s=>s.ran(/^pg_restore -l/)},
  {t:"Khôi phục vào CSDL thử mes_restore (tạo CSDL trước).",ok:"Sao lưu chưa từng khôi phục thử thì chưa phải sao lưu.",check:s=>s.S.rest},
  {t:"Kiểm bản khôi phục: đếm state_event và chạy 02_oee.sql cho ca chuẩn.",ok:"0,7556: dữ liệu khôi phục cho ra đúng đáp án. Ghi lại thời gian để biết RTO thật.",check:s=>s.ran(/02_oee/)&&s.ran(/count/)}]}));

